def _ordered_waves(items: list[WorkItem]) -> list[list[str]]:
    remaining = {item.id: set(item.depends_on) for item in items}
    waves = []
    completed = set()
    while remaining:
        ready = sorted(node for node, deps in remaining.items() if deps <= completed)
        if not ready:
            raise ValueError("cycle: " + ", ".join(_cycle_report(remaining)))
        waves.append(ready)
        completed.update(ready)
        for node in ready:
            del remaining[node]
    return waves
